import{_ as l,C as a,o as h,c as s,j as d,a as c,E as e,aj as r}from"./chunks/framework.DkvuVDKz.js";const x=JSON.parse('{"title":"ColorSwatchPicker 颜色色块选择器","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-swatch-picker.md","filePath":"components/color-swatch-picker.md","lastUpdated":1789421164000}'),n={name:"components/color-swatch-picker.md"},b={id:"colorswatchpicker-颜色色块选择器",tabindex:"-1"};function p(u,t,k,w,f,g){const i=a("Badge"),o=a("XhDemo");return h(),s("div",null,[d("h1",b,[t[0]||(t[0]=c("ColorSwatchPicker 颜色色块选择器 ",-1)),e(i,{type:"info",text:"alpha"}),t[1]||(t[1]=c()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#colorswatchpicker-颜色色块选择器","aria-label":'Permalink to "ColorSwatchPicker 颜色色块选择器 <Badge type="info" text="alpha" />"'},"​",-1))]),t[3]||(t[3]=r('<p>从一组固定颜色里挑一个：主题色、标签色、高亮色。 每格是一颗 <code>role=radio</code> 的色块，整组是一个 <code>radiogroup</code>——它就是一个把选项画成颜色的<a href="./radio-group">单选组</a>。 只想自由调出任意颜色时用<a href="./color-picker">颜色选择器</a>；它内嵌的预设色板用的就是这一件。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/color-swatch-picker" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/color-swatch-picker.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/color-swatch-picker" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/color-swatch-picker" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/color-swatch-picker.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>交一组颜色数据就自动铺开；每格是一颗 radio，方向键在格子间移动并选中</p>',4)),e(o,{src:"color-swatch-picker/01-basic"}),t[4]||(t[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;color-swatch-picker&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>item</code></strong> · <strong><code>swatch</code></strong> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="手写格子" tabindex="-1">手写格子 <a class="header-anchor" href="#手写格子" aria-label="Permalink to &quot;手写格子&quot;">​</a></h3><p>不交数据也行：每格自己报 value，名字与禁用写在格子上；半透明颜色铺在棋盘格上</p>',6)),e(o,{src:"color-swatch-picker/02-items"}),t[5]||(t[5]=d("h3",{id:"状态",tabindex:"-1"},[c("状态 "),d("a",{class:"header-anchor",href:"#状态","aria-label":'Permalink to "状态"'},"​")],-1)),t[6]||(t[6]=d("p",null,"禁用整组置灰、只读只挡落值不挡焦点、无效把描边转成警示色",-1)),e(o,{src:"color-swatch-picker/03-states"}),t[7]||(t[7]=d("h3",{id:"尺寸与语气",tabindex:"-1"},[c("尺寸与语气 "),d("a",{class:"header-anchor",href:"#尺寸与语气","aria-label":'Permalink to "尺寸与语气"'},"​")],-1)),t[8]||(t[8]=d("p",null,"格子边长跟着控件行高走三档；tone 决定选中环与选中标记用哪族颜色",-1)),e(o,{src:"color-swatch-picker/04-size-tone"}),t[9]||(t[9]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>可选的颜色是有限的一组，且每个颜色都有它的含义（品牌色、状态色、日历分类色）。</li><li>想让人一眼看到全部选项再挑，不用打开浮层。</li><li>表单里要提交一个颜色串，且不需要自由调色。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>要自由调出任意颜色：用<a href="./color-picker">颜色选择器</a>，它把这一组色板和取色面装在一起。</li><li>只是展示一个颜色、不接选择：用<a href="./color-swatch">颜色色块</a>。</li><li>让人手输颜色串：用<a href="./color-field">颜色字段</a>。</li><li>选项不是颜色而是文字：那是<a href="./radio-group">单选组</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>选中按颜色比不按串比：<code>rgb(255, 0, 0)</code> 与 <code>#ff0000</code> 是同一格，受控 <code>value</code> 用哪种写法都能对上格子。</li><li>与单选组同一套 roving tabindex：整组只占一个 Tab 位，四个方向键在格子间移焦点并选中，走到尽头回绕，禁用格跳过；Space 选中当前格。</li><li>焦点从组外进来时落在已选中的那一格，一个都没选才落第一格。</li><li><code>swatches</code> 给数据：可及名字与禁用从数据里查，格子部件只需报 <code>value</code>；不写默认内容时按数据自动铺开。</li><li>每格的色块面由 Swatch 家族画：解析不出的串只剩棋盘格，半透明颜色铺在棋盘格上。</li><li><code>readOnly</code> 时方向键照常移焦点但不落值；<code>disabled</code> 整组置灰，格子仍可聚焦。</li><li>尺寸 sm / md / lg 三档：格子边长跟着控件行高走，与旁边的按钮、字段齐高。</li><li>选中环与选中标记随 <code>data-tone</code> 走；标记自带一圈画布色描边，落在任何颜色上都看得出来。</li><li>高对比模式下色块保住原色，选中环与标记换系统高亮色；打印时标记改画成实边。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>内嵌在<a href="./color-picker">颜色选择器</a>的浮层里当预设色板。</li><li>与<a href="./color-field">颜色字段</a>并排：色板挑常用色，字段手输精确值。</li><li>放进<a href="./field">表单字段</a>里承接标题、说明与错误信息，<code>disabled</code> / <code>readOnly</code> / <code>invalid</code> / <code>required</code> 随字段下发。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>每格给名字（<code>swatches[].label</code> 或部件的 <code>label</code>），读屏用户听到的应是「品牌红」而不是 <code>#e11d48</code>。</li><li>色板的颜色数量控制在一眼能扫完的范围，再多就该换<a href="./color-picker">颜色选择器</a>。</li><li>选中值有初始值时用 <code>defaultValue</code>，让焦点进组时直接落在它上面。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>拿它做多选：一格只能选中一个，要多选颜色请用<a href="./checkbox-group">复选框组</a>配<a href="./color-swatch">颜色色块</a>。</li><li>把颜色写成 <code>red</code> 这类关键字：它们不在支持的写法里，那一格只会画成棋盘格。</li><li>同一组里放两格同一个颜色的不同写法：它们会同时算作选中。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-color-swatch-picker&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhColorSwatchPickerItem</code> <code>XhColorSwatchPickerLabel</code> <code>XhColorSwatchPickerRoot</code></td></tr><tr><td>组合式函数</td><td><code>useColorSwatchPicker</code></td></tr><tr><td>状态机</td><td><code>colorSwatchPickerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/color-swatch-picker.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>swatches</code></td><td><code>ColorSwatchPickerNode[]</code></td><td></td><td>格子数据，可及名字与禁用的事实源。给了它，格子部件只需报 value。 缺省即回到「名字与禁用都写在格子部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中的颜色串。给定即受控：写只发 onValueChange 不落内部值。写法不同的同一个颜色也算选中。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：选不动，但仍可聚焦、方向键照常移焦点，对比度不降。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改呈现，不挡交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起用，只发无障碍属性，不自行拦提交。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 &#39;ltr&#39;；只改写左右两键的语义。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，换的是格子的边长与间距。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：决定选中环与选中标记用哪族颜色。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ColorSwatchPickerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ColorSwatchPickerValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ColorSwatchPickerValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhColorSwatchPickerRoot</code></td><td><code>default</code></td><td><code>ColorSwatchPickerRootSlotProps</code></td><td></td></tr><tr><td><code>XhColorSwatchPickerRoot</code></td><td><code>label</code></td><td>—</td><td></td></tr></tbody></table><h3 id="状态-1" tabindex="-1">状态 <a class="header-anchor" href="#状态-1" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>FORM.RESET</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>swatches</code></td><td><code>readonly ColorSwatchPickerNodeMeta[]</code></td><td>swatches 推出的格子元信息，按数据顺序排列；没给 swatches 即空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td>某个颜色串是不是当前选中的那一格：写法不同（<code>#f00</code> 与 <code>rgb(255,0,0)</code>）也算同一个。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>一格：role=radio，颜色串是它的身份。</td></tr><tr><td><code>getSwatchProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>格里的色块面：走 Swatch 家族画颜色，纯装饰。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>选中标记（对号），纯装饰。</td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;input&#39;]</code></td><td>格子对应的隐藏原生 radio 输入，用于表单提交。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点格子（即选中的那格）；落到容器上时由容器转投锚点格子，锚点缺席或被禁用才落首个可停留格</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in group, group not disabled</td><td>焦点移到下一个可停留格并选中，末格回绕到首格；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in group, group not disabled</td><td>焦点移到上一个可停留格并选中，首格回绕到末格；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Space</code></td><td>focus on item, item not disabled</td><td>选中当前格</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-label</code></td><td>label.group</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>itemLabel(item)</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>role=radiogroup</code>，名字取 label 部件，没放时读 <code>translations.group</code>。</li><li>每格是 <code>role=radio</code> 并显式输出 <code>aria-checked</code>；名字按 <code>label</code> → <code>swatches</code> 里的 <code>label</code> → <code>translations.swatch(value)</code> 依次取，光看颜色串听不出含义时务必给名字。</li><li>禁用格用 <code>aria-disabled</code> 表达，仍可聚焦、仍是方向键的起点。</li><li>每格内一份 <code>inert</code> 的隐藏原生 radio 承接表单提交，不进焦点序列与可访问树。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/color-swatch-picker.css</code> 使用 <code>[data-scope=&quot;color-swatch-picker&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>swatch</code></td><td><code>data-xh-swatch</code></td><td>&#39;&#39;</td></tr><tr><td><code>swatch</code></td><td><code>data-xh-swatch-size</code></td><td>props.size</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-color-swatch-picker-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-gap</code></td><td>color-swatch-picker 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-mark</code></td><td>color-swatch-picker 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-accent</code></td><td>color-swatch-picker 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-border</code></td><td><code>indicator</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-bg-canvas</code></td><td>color-swatch-picker 的 indicator 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-fg</code></td><td><code>indicator</code></td><td><code>background-color</code><br><code>color</code></td><td><code>default</code><br><code>empty</code></td><td><code>--xh-_tone-on</code></td><td>color-swatch-picker 的 indicator 部件 background-color、color 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-size</code></td><td><code>indicator</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-indicator</code></td><td>color-swatch-picker 的 indicator 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-item-radius</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-radius</code><br><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-radius、border-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-item-size</code></td><td><code>item</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-cell</code></td><td>color-swatch-picker 的 item 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>color-swatch-picker 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-font-size</code></td><td>color-swatch-picker 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>color-swatch-picker 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-ring</code></td><td><code>item</code></td><td><code>outline</code></td><td><code>state=checked</code></td><td><code>--xh-_color-swatch-picker-accent</code></td><td>color-swatch-picker 的 item 部件 outline 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border</code></td><td><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>color-swatch-picker 的 swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border-hover</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled], [data-readonly])</code><br><code>readonly</code></td><td><code>--xh-border-strong</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border-invalid</code></td><td><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>color-swatch-picker 的 swatch 部件 --xh-swatch-border 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>border-color</code> · <code>opacity</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><ul><li>格子排成可换行的网格，一行摆不下时落到下一行；粗指针下命中区就是整格。</li></ul><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><ul><li><code>dir=&quot;rtl&quot;</code> 只对调左右方向键的语义，上下键不受影响；格子的排列顺序由文档方向决定。</li></ul>',56))])}const P=l(n,[["render",p]]);export{x as __pageData,P as default};
